"""Conversions between the application models and the "customers" table: what the service takes and returns."""

from __future__ import annotations

from typing import Any

from shop.models import Address, Customer as CustomerModel, Level, Location

from app.customer.entity import Customer


def _plain(value: Any) -> Any:
    """The value of an enum member, or the value itself."""
    return getattr(value, "value", value)


def _customer_address_location_to_document(value: Location) -> Any:
    """A Location as the customers collection keeps it; what is missing is left out."""
    document = {
        "latitude": value.latitude,
        "longitude": value.longitude,
    }
    return {key: item for key, item in document.items() if item is not None}


def _customer_address_to_document(value: Address) -> Any:
    """An Address as the customers collection keeps it; what is missing is left out."""
    document = {
        "street": value.street,
        "zip code": value.zip_code,
        "location": _customer_address_location_to_document(value.location) if value.location is not None else None,
    }
    return {key: item for key, item in document.items() if item is not None}


def customer_model_to_customer(model: CustomerModel) -> Customer:
    """A Customer as the customers table takes it."""
    return Customer(
        email=model.email,
        level=_plain(model.level) if model.level is not None else None,
        since=model.since,
        address=_customer_address_to_document(model.address),
        tags=model.tags,
    )


def _customer_address_location_from_document(value: Any) -> Location:
    """A document of the customers collection as a Location."""
    return Location(
        latitude=value["latitude"],
        longitude=value["longitude"],
    )


def _customer_address_from_document(value: Any) -> Address:
    """A document of the customers collection as an Address."""
    return Address(
        street=value["street"],
        zip_code=value["zip code"],
        location=_customer_address_location_from_document(value.get("location")) if value.get("location") is not None else None,
    )


def customer_to_customer_model(row: Customer) -> CustomerModel:
    """A row of the customers table as a Customer."""
    return CustomerModel(
        id=row.id,
        email=row.email,
        level=Level(row.level) if row.level is not None else None,
        since=row.since,
        address=_customer_address_from_document(row.address),
        tags=row.tags if row.tags is not None else [],
    )

