"""Conversions between the application models and the "orders" table: what the service takes and returns."""

from __future__ import annotations

from datetime import datetime, timezone
from typing import Any

from shop.models import Discount, LineStatus, Order as OrderModel, OrderLine, Shipping

from app.order.entity import Order


def _plain(value: Any) -> Any:
    """The value of an enum member, or the value itself."""
    return getattr(value, "value", value)


def _order_lines_discounts_to_document(value: Discount) -> Any:
    """A Discount as the orders collection keeps it; what is missing is left out."""
    document = {
        "reason": value.reason,
        "percent": value.percent,
    }
    return {key: item for key, item in document.items() if item is not None}


def _order_lines_to_document(value: OrderLine) -> Any:
    """An OrderLine as the orders collection keeps it; what is missing is left out."""
    document = {
        "_id": value.id,
        "sku": value.sku,
        "quantity": value.quantity,
        "price": value.price,
        "status": _plain(value.status) if value.status is not None else None,
        "discounts": [_order_lines_discounts_to_document(item) for item in value.discounts],
    }
    return {key: item for key, item in document.items() if item is not None}


def _order_shipping_to_document(value: Shipping) -> Any:
    """A Shipping as the orders collection keeps it; what is missing is left out."""
    document = {
        "carrier": value.carrier,
        "sentOn": datetime(value.sent_on.year, value.sent_on.month, value.sent_on.day, tzinfo=timezone.utc),
    }
    return {key: item for key, item in document.items() if item is not None}


def order_model_to_order(model: OrderModel) -> Order:
    """An Order as the orders table takes it."""
    return Order(
        code=model.code,
        lines=[_order_lines_to_document(item) for item in model.lines],
        shipping=_order_shipping_to_document(model.shipping) if model.shipping is not None else None,
    )


def _order_lines_discounts_from_document(value: Any) -> Discount:
    """A document of the orders collection as a Discount."""
    return Discount(
        reason=value["reason"],
        percent=value["percent"],
    )


def _order_lines_from_document(value: Any) -> OrderLine:
    """A document of the orders collection as an OrderLine."""
    return OrderLine(
        id=value.get("_id"),
        sku=value["sku"],
        quantity=value["quantity"],
        price=value["price"],
        status=LineStatus(value.get("status")) if value.get("status") is not None else None,
        discounts=[_order_lines_discounts_from_document(item) for item in value.get("discounts")] if value.get("discounts") is not None else [],
    )


def _order_shipping_from_document(value: Any) -> Shipping:
    """A document of the orders collection as a Shipping."""
    return Shipping(
        carrier=value["carrier"],
        sent_on=value["sentOn"].date(),
    )


def order_to_order_model(row: Order) -> OrderModel:
    """A row of the orders table as an Order."""
    return OrderModel(
        id=row.id,
        code=row.code,
        lines=[_order_lines_from_document(item) for item in row.lines],
        shipping=_order_shipping_from_document(row.shipping) if row.shipping is not None else None,
    )

