from __future__ import annotations

from dataclasses import dataclass
from typing import NotRequired, TypedDict


ShipmentParcelSize = TypedDict(
    "ShipmentParcelSize",
    {
        "height": float,
    },
)
"""A document inside another, by the stored names of its fields."""


ShipmentParcel = TypedDict(
    "ShipmentParcel",
    {
        "weight": float,
        "contents": str,
        "size": NotRequired[ShipmentParcelSize | None],
    },
)
"""A document inside another, by the stored names of its fields."""


ShipmentStop = TypedDict(
    "ShipmentStop",
    {
        "city": NotRequired[str | None],
    },
)
"""A document inside another, by the stored names of its fields."""


@dataclass(kw_only=True, eq=False)
class Shipment:
    """A document of the "shipments" collection. An attribute stays None until it is set or read."""

    id: str | None = None
    parcel: ShipmentParcel | None = None
    stops: list[ShipmentStop] | None = None

